cd /app/work && python3 - <<'EOF'
import json
req=json.load(open('fail.json')); exp=json.load(open('expected.json')); got=json.load(open('got.json'))
for a,b in zip(exp['results'],got['results']):
    if a!=b:
        print('TRACE', a['id'])
        for x,y in zip(a['packets'],b['packets']):
            if x!=y: print(' exp',x,'\n got',y)
        if a['connection']!=b['connection']: print(' conn exp',a['connection'],'\n      got',b['connection'])
        for k in ('keys','received_total','streams','crypto'):
            if a[k]!=b[k]: print(' %s exp %s\n      got %s'%(k,json.dumps(a[k]),json.dumps(b[k])))
print(json.dumps(req['traces'][0]['config']))
print(json.dumps(req['traces'][0]['events'],indent=1)[:4000])
EOF
